class Solution {
    public int findDuplicate(int[] nums) {
        int lo = 0, hi = nums.length;                   // 在 [lo, hi) 里找第一个「≤ x 的数超过 x 个」的 x
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            int cnt = 0;
            for (int v : nums) {
                if (v <= mid) cnt++;
            }
            if (cnt > mid) {                            // 重复的数 ≤ mid
                hi = mid;
            } else {
                lo = mid + 1;
            }
        }
        return lo;
    }
}

